"""Compare independently built pre/post-migration SDKs on identical offline inputs.

Run from any directory:
  python3 sdk/tests/fixtures/crypto/compare_asn1.py --output /absolute/empty/directory

Requires Python 3, Git, and Rust 1.96.0 with the host's normal OpenSSL build tools.
No live TSA/OCSP service is used. Sources are exported with git archive, never
checked out over the caller's worktree. The same inline probes are injected into
both exports. Only the clock, ephemeral RNG, and test-only visibility are patched;
no ASN.1 codec, verification, request, or certificate-generation logic is replaced.

OpenSSL builds produce artifacts using each revision's existing test generators
and real ephemeral-certificate generator. Both revisions then verify the combined
old/new/fixed corpus with OpenSSL and Rust-native backends. All raw observations,
generated bytes, source overlays, exact revisions, dependency locks and command
logs remain in --output. Timestamp EC keys remain random: their generated bytes
are shared between all four consumers, not compared for producer byte equality.
Ephemeral keys and the existing OCSP issuer generator are deterministic.
"""

import argparse
import base64
import hashlib
import io
import json
import os
from pathlib import Path
import shutil
import subprocess
import tarfile


OLD = "7905e58f443b20d7e102dd9883b6600513a64771"
CLOCK = 1_768_478_400  # 2026-01-15T12:00:00Z

PROBE = r'''
#[cfg(all(test, not(target_arch = "wasm32")))]
#[allow(clippy::unwrap_used)]
pub(crate) mod compat_probe {
    use std::{collections::BTreeMap, fs, path::{Path, PathBuf}};
    use serde_json::{json, Value};
    use crate::{
        crypto::{
            cose::{check_certificate_profile, CertificateTrustPolicy},
            ocsp::{self, OcspResponse},
            time_stamp::{tsa_signer_cert_der_from_token, verify_time_stamp},
        },
        status_tracker::StatusTracker,
        utils::ephemeral_cert::generate_ephemeral_chain,
    };

    pub(crate) fn write(name: &str, data: impl AsRef<[u8]>) {
        fs::write(Path::new(&std::env::var("ASN1_COMPAT_EXPORT").unwrap()).join(name), data).unwrap();
    }

    fn log(log: &StatusTracker) -> Value {
        json!(log.logged_items().iter().map(|item| json!({
            "kind": format!("{:?}", item.kind),
            "code": item.validation_status,
            "description": item.description,
            "error": item.err_val,
        })).collect::<Vec<_>>())
    }

    fn files(path: &Path) -> Vec<PathBuf> {
        let mut result = Vec::new();
        for entry in fs::read_dir(path).unwrap() {
            let path = entry.unwrap().path();
            if path.is_dir() { result.extend(files(&path)); } else { result.push(path); }
        }
        result.sort();
        result
    }

    #[test]
    fn compat_export_artifacts() {
        if std::env::var_os("ASN1_COMPAT_EXPORT").is_none() { return; }
        let ephemeral = generate_ephemeral_chain("cross-build.example").unwrap();
        write("ephemeral.ee", &ephemeral.ee_der);
        write("ephemeral.ca", &ephemeral.ca_der);
        let issuer = ocsp::test_responder::IssuerResponder::new();
        for by_name in [false, true] {
            let label = if by_name { "by-name" } else { "by-key" };
            let basic = issuer.basic_response(by_name);
            write(&format!("issuer-{label}.ocsp"), issuer.sign(basic.clone()));
            write(&format!("delegated-{label}.ocsp"), issuer.delegated_response(basic.clone()));
            let mut empty = basic;
            empty.tbs_response_data.responses.clear();
            write(&format!("empty-{label}.ocsp"), issuer.sign(empty));
            for name in ["issuer", "delegated", "empty"] {
                write(&format!("{name}-{label}.chain"), serde_json::to_vec(&issuer.chain).unwrap());
            }
        }
    }

    #[test]
    fn compat_observe_corpus() {
        let Some(root) = std::env::var_os("ASN1_COMPAT_CORPUS") else { return; };
        let root = Path::new(&root);
        let mut observations = BTreeMap::new();
        for path in files(root) {
            let name = path.strip_prefix(root).unwrap().to_string_lossy().to_string();
            let bytes = fs::read(&path).unwrap();
            let policy = CertificateTrustPolicy::default();
            match path.extension().and_then(|ext| ext.to_str()) {
                Some("tst") => {
                    let data = fs::read(path.with_extension("data")).unwrap();
                    for (label, data) in [("matching", data.as_slice()), ("wrong", b"wrong".as_slice())] {
                        let mut tracker = StatusTracker::default();
                        let result = verify_time_stamp(&bytes, data, &policy, &mut tracker, false);
                        observations.insert(format!("{name}/{label}"), json!({
                            "result": format!("{result:?}"),
                            "log": log(&tracker),
                            "signer": format!("{:?}", tsa_signer_cert_der_from_token(&bytes)
                                .map(|cert| cert.map(|cert| hex::encode(crate::crypto::hash::sha256(&cert))))),
                        }));
                    }
                }
                Some("ocsp") => {
                    let chain: Vec<Vec<u8>> = serde_json::from_slice(
                        &fs::read(path.with_extension("chain")).unwrap()).unwrap();
                    let request = ocsp::compat_probe_request(&chain[0], &chain[1]);
                    for (label, signing_time) in [
                        ("attested", chrono::DateTime::from_timestamp(1_675_238_400, 0)),
                        ("current", None),
                    ] {
                        let mut tracker = StatusTracker::default();
                        let result = OcspResponse::from_der_checked_at(
                            &bytes, &chain, signing_time,
                            crate::crypto::internal::time::utc_now(), &mut tracker);
                        let result = match result {
                            Ok(response) => json!({
                                "serial": response.certificate_serial_num,
                                "next_update": response.next_update,
                                "revoked_at": response.revoked_at,
                                "certificates": response.ocsp_certs.map(|certs| certs.iter()
                                    .map(|cert| hex::encode(crate::crypto::hash::sha256(cert)))
                                    .collect::<Vec<_>>()),
                            }),
                            Err(error) => json!({"error": format!("{error:?}")}),
                        };
                        observations.insert(format!("{name}/{label}"), json!({
                            "result": result, "log": log(&tracker), "request": request,
                        }));
                    }
                }
                Some("ee" | "ca") => {
                    let mut tracker = StatusTracker::default();
                    let result = check_certificate_profile(&bytes, &policy, &mut tracker, None);
                    let (_, cert) = x509_parser::parse_x509_certificate(&bytes).unwrap();
                    let issuer_path = path.with_extension("ca");
                    let issuer_bytes = fs::read(issuer_path).unwrap();
                    let (_, issuer) = x509_parser::parse_x509_certificate(&issuer_bytes).unwrap();
                    let key = ed25519_dalek::VerifyingKey::from_bytes(
                        issuer.public_key().subject_public_key.data.as_ref().try_into().unwrap()).unwrap();
                    let signature = ed25519_dalek::Signature::from_slice(
                        cert.signature_value.data.as_ref()).unwrap();
                    observations.insert(name, json!({
                        "profile": format!("{result:?}"), "log": log(&tracker),
                        "signature": format!("{:?}", key.verify_strict(cert.tbs_certificate.as_ref(), &signature)),
                        "subject": cert.subject().to_string(), "issuer": cert.issuer().to_string(),
                        "not_before": cert.validity().not_before.timestamp(),
                        "not_after": cert.validity().not_after.timestamp(),
                        "extensions": cert.extensions().iter().map(|ext| json!({
                            "oid": ext.oid.to_id_string(), "critical": ext.critical,
                            "value": hex::encode(ext.value),
                        })).collect::<Vec<_>>(),
                    }));
                }
                _ => {}
            }
        }
        fs::write(std::env::var("ASN1_COMPAT_REPORT").unwrap(),
            serde_json::to_vec_pretty(&observations).unwrap()).unwrap();
    }
}
'''

TIMESTAMPS = r'''
    #[test]
    fn compat_export_timestamps() {
        if std::env::var_os("ASN1_COMPAT_EXPORT").is_none() { return; }
        let data = b"claim signature bytes";
        for (name, oid, digest) in [
            ("md5", OID_MD5, MessageDigest::md5()),
            ("sha1", OID_SHA1, MessageDigest::sha1()),
            ("sha224", OID_SHA224, MessageDigest::sha224()),
            ("sha256", OID_SHA256, MessageDigest::sha256()),
            ("sha384", OID_SHA384, MessageDigest::sha384()),
            ("sha512", OID_SHA512, MessageDigest::sha512()),
        ] {
            for signed_attrs in [false, true] {
                let name = format!("{name}-attrs-{signed_attrs}");
                let token = build_token_with(oid, digest, data, TokenOptions {
                    signed_attrs, ..Default::default()
                });
                crate::crypto::compat_probe::write(&format!("{name}.tst"), &token);
                crate::crypto::compat_probe::write(&format!("{name}.data"), data);
            }
        }
        for (name, time, validity) in [
            ("pre-epoch", b"20200101000000Z".as_slice(), (-631_152_000, 1_900_000_000)),
            ("fractional", b"20200101000000.123456Z".as_slice(), (1_500_000_000, 1_900_000_000)),
            ("2050", b"20500101000000Z".as_slice(), (1_500_000_000, 2_600_000_000)),
        ] {
            let token = build_token_with(OID_SHA256, MessageDigest::sha256(), data, TokenOptions {
                signed_attrs: true, gen_time: Some(time), certificate_validity: Some(validity),
                ..Default::default()
            });
            crate::crypto::compat_probe::write(&format!("{name}.tst"), token);
            crate::crypto::compat_probe::write(&format!("{name}.data"), data);
        }
    }
'''

ADVERSARIAL = r'''
    #[test]
    fn compat_export_adversarial_timestamps() {
        if std::env::var_os("ASN1_COMPAT_EXPORT").is_none() { return; }
        let signer = original_signer_info(TOKEN);
        crate::crypto::compat_probe::write(
            "duplicate-signers.tst", rebuild_token(TOKEN, None, &[signer.clone(), signer]));
        crate::crypto::compat_probe::write("duplicate-signers.data", DATA);
        for keep_original in [false, true] {
            for original_first in [false, true] {
                let name = format!("forged-{keep_original}-{original_first}");
                crate::crypto::compat_probe::write(
                    &format!("{name}.tst"), forged_token(TOKEN, keep_original, original_first));
                crate::crypto::compat_probe::write(&format!("{name}.data"), FORGED_DATA);
            }
        }
    }
'''

REQUEST = r'''
#[cfg(test)]
pub(crate) fn compat_probe_request(subject: &[u8], issuer: &[u8]) -> Option<String> {
    build_ocsp_request(subject, issuer, "https://offline.invalid/ocsp").map(|request| request.request_str)
}
'''


def command(args, cwd, log, env=None):
    with log.open("wb") as stream:
        subprocess.run(args, cwd=cwd, env=env, stdout=stream, stderr=subprocess.STDOUT, check=True)


def replace_once(path, old, new):
    text = path.read_text()
    if text.count(old) != 1:
        raise RuntimeError(f"Expected exactly one {old!r} in {path}")
    path.write_text(text.replace(old, new))


def replace_body(path, signature, body):
    text = path.read_text()
    start = text.index("{", text.index(signature))
    depth = 1
    end = start + 1
    while depth:
        depth += (text[end] == "{") - (text[end] == "}")
        end += 1
    path.write_text(text[:start + 1] + body + text[end - 1:])


def inject(source):
    crypto = source / "sdk/src/crypto"
    with (crypto / "mod.rs").open("a") as stream:
        stream.write(PROBE)
    replace_body(crypto / "internal/time.rs", "pub(crate) fn utc_now()", f"""
    chrono::DateTime::from_timestamp({CLOCK}, 0).unwrap()
""")
    replace_body(source / "sdk/src/utils/ephemeral_cert.rs", "fn fill_random(", """
    static SEED: std::sync::atomic::AtomicU8 = std::sync::atomic::AtomicU8::new(1);
    buf.fill(SEED.fetch_add(1, std::sync::atomic::Ordering::SeqCst));
    Ok(())
""")
    # The old generator called Utc directly; the new one uses the shared clock.
    path = source / "sdk/src/utils/ephemeral_cert.rs"
    path.write_text(path.read_text().replace("Utc::now()", "crate::crypto::internal::time::utc_now()"))
    replace_once(crypto / "ocsp/mod.rs", "    fn from_der_checked_at(", "    pub(crate) fn from_der_checked_at(")
    with (crypto / "ocsp/mod.rs").open("a") as stream:
        stream.write("""
#[cfg(test)]
pub(crate) use fetch::compat_probe_request;
""")
    with (crypto / "ocsp/fetch.rs").open("a") as stream:
        stream.write(REQUEST)
    path = crypto / "time_stamp/verify.rs"
    text = path.read_text()
    for module, probe in [("message_imprint_regression", TIMESTAMPS), ("signed_attrs_tests", ADVERSARIAL)]:
        start = text.index("{", text.index(f"mod {module}"))
        depth, end = 1, start + 1
        while depth:
            depth += (text[end] == "{") - (text[end] == "}")
            end += 1
        text = text[:end - 1] + probe + text[end - 1:]
    path.write_text(text)


def snapshot(repo, revision, target):
    target.mkdir()
    archive = subprocess.check_output(["git", "archive", revision], cwd=repo)
    with tarfile.open(fileobj=io.BytesIO(archive)) as tar:
        # Both inputs must be explicitly trusted repository revisions.
        tar.extractall(target, filter="data")
    inject(target)


def fixed_corpus(old, target):
    target.mkdir()
    fixtures = old / "sdk/tests/fixtures/crypto"
    for path in (fixtures / "time_stamp").glob("*.tst"):
        shutil.copyfile(path, target / path.name)
        data = (b"RSA timestamp regression" if path.name.startswith(("ps", "rsa-"))
                else b"some sample content to sign")
        (target / path.with_suffix(".data").name).write_bytes(data)
    chain = []
    pem = (fixtures / "ocsp/ocsp_chain.pem").read_text()
    for part in pem.split("-----BEGIN CERTIFICATE-----")[1:]:
        chain.append(list(base64.b64decode(part.split("-----END CERTIFICATE-----")[0])))
    for path in (fixtures / "ocsp").glob("response_*.der"):
        name = path.stem
        shutil.copyfile(path, target / f"{name}.ocsp")
        (target / f"{name}.chain").write_text(json.dumps(chain))


def damaged_inputs(corpus):
    for directory in sorted(corpus.iterdir()):
        for path in sorted(directory.iterdir()):
            if path.suffix not in (".tst", ".ocsp"):
                continue
            data = path.read_bytes()
            sidecar = path.with_suffix(".data" if path.suffix == ".tst" else ".chain")
            for label, mutated in [("truncated", data[:-1]), ("trailing", data + b"\x00")]:
                target = path.with_name(label + "-" + path.name)
                target.write_bytes(mutated)
                shutil.copyfile(sidecar, target.with_suffix(sidecar.suffix))
            if path.suffix == ".ocsp":
                # Mutate a digit in the signed producedAt, preserving lengths and
                # parseability. A valid envelope must not imply a valid signature.
                position = data.index(b"\x18\x0f") + 5
                target = path.with_name("tampered-" + path.name)
                digit = b"2" if data[position] != ord("2") else b"3"
                target.write_bytes(data[:position] + digit + data[position + 1:])
                shutil.copyfile(sidecar, target.with_suffix(".chain"))


def expected_century_fix(case, label, old, new):
    if (label not in ("new-openssl", "new-native")
            or case.split("/")[1] not in ("pre-epoch.tst", "trailing-pre-epoch.tst")):
        return False
    expected_result = "Err(InvalidData)" if case.endswith("/wrong") else "Ok(TstInfo {"
    return (
        old["result"] == "Err(ExpiredCertificate)"
        and new["result"].startswith(expected_result)
        and old["signer"] == new["signer"]
        and [item["code"] for item in old["log"]] == ["timeStamp.outsideValidity"]
        and [item["code"] for item in new["log"]] == (
            ["timeStamp.mismatch"] if case.endswith("/wrong")
            else ["timeStamp.validated", "timeStamp.trusted"]
        )
    )


def compare(reports):
    differences = []
    reference = json.loads(reports["old-openssl"].read_text())
    for label, report in reports.items():
        current = json.loads(report.read_text())
        for key in sorted(reference.keys() | current.keys()):
            if reference.get(key) != current.get(key):
                differences.append({"consumer": label, "case": key,
                                    "expected_century_fix": expected_century_fix(
                                        key, label, reference.get(key), current.get(key)),
                                    "old_openssl": reference.get(key), "observed": current.get(key)})
    return differences


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--old", default=OLD)
    parser.add_argument("--new", default="HEAD")
    parser.add_argument("--toolchain", default="1.96.0")
    parser.add_argument("--target-dir", type=Path, help="Reuse a caller-owned Cargo target directory")
    parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()
    repo = Path(subprocess.check_output(["git", "rev-parse", "--show-toplevel"], text=True).strip())
    output = args.output.resolve()
    output.mkdir(parents=True, exist_ok=True)
    if any(output.iterdir()):
        raise RuntimeError("--output must be empty")
    revisions = {name: subprocess.check_output(["git", "rev-parse", ref], cwd=repo, text=True).strip()
                 for name, ref in [("old", args.old), ("new", args.new)]}
    (output / "revisions.json").write_text(json.dumps({
        **revisions, "toolchain": args.toolchain, "clock": CLOCK,
        "probe_sha256": hashlib.sha256((PROBE + TIMESTAMPS + ADVERSARIAL + REQUEST).encode()).hexdigest(),
    }, indent=2))
    corpus = output / "corpus"
    corpus.mkdir()
    env = {**os.environ, "CARGO_TARGET_DIR": str((args.target_dir or output / "target").resolve()),
           "CARGO_INCREMENTAL": "0"}
    for label, revision in revisions.items():
        source = output / label
        snapshot(repo, revision, source)
        generated = corpus / label
        generated.mkdir()
        print(f"Generating {label}: {revision}", flush=True)
        command(["cargo", f"+{args.toolchain}", "test", "-q", "-p", "c2pa", "--lib",
                 "compat_export", "--", "--test-threads=1"], source, output / f"{label}-export.log",
                {**env, "ASN1_COMPAT_EXPORT": str(generated)})
    fixed_corpus(output / "old", corpus / "fixed")
    damaged_inputs(corpus)
    reports = {}
    for label in revisions:
        for backend in ("openssl", "native"):
            name = f"{label}-{backend}"
            report = output / f"{name}.json"
            args_ = ["cargo", f"+{args.toolchain}", "test", "-q", "-p", "c2pa", "--lib"]
            if backend == "native":
                args_ += ["--no-default-features", "--features", "rust_native_crypto"]
            args_ += ["compat_observe_corpus", "--", "--test-threads=1"]
            print(f"Observing corpus: {name}", flush=True)
            command(args_, output / label, output / f"{name}.log",
                    {**env, "ASN1_COMPAT_CORPUS": str(corpus), "ASN1_COMPAT_REPORT": str(report)})
            reports[name] = report
    differences = compare(reports)
    (output / "differences.json").write_text(json.dumps(differences, indent=2))
    byte_comparisons = {}
    for path in sorted((corpus / "old").iterdir()):
        if path.suffix in (".ee", ".ca", ".ocsp", ".chain"):
            byte_comparisons[path.name] = path.read_bytes() == (corpus / "new" / path.name).read_bytes()
    summary = {
        "observations_per_consumer": len(json.loads(reports["old-openssl"].read_text())),
        "consumer_count": len(reports), "differences": len(differences),
        "expected_century_fix": sum(d["expected_century_fix"] for d in differences),
        "unexpected_differences": sum(not d["expected_century_fix"] for d in differences),
        "deterministic_producer_bytes_equal": byte_comparisons,
    }
    (output / "summary.json").write_text(json.dumps(summary, indent=2))
    print(json.dumps(summary, indent=2))
    if any(not d["expected_century_fix"] for d in differences) or not all(byte_comparisons.values()):
        raise SystemExit("Differences recorded; investigate differences.json (nothing is normalized away).")


if __name__ == "__main__":
    main()
